/**
 * plank-join.mjs — Shipshape plank-join checker.
 *
 * Scans implementation and specs directories, reports:
 *   - Every @planks(token) whose token matches no step-definition pattern
 *   - Every @planks-provisional(ref) whose referenced scenario lost its @captain tag
 *   - Every behaviour-bearing step-definition pattern with no matching @planks token
 *
 * Exits 0 when the join is clean, 1 otherwise.
 */

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, '..');

const IMPL_DIRS = [path.join(ROOT, 'js')];
const SPECS_DIR = path.join(ROOT, 'features');
const SUPPORT_DIR = path.join(ROOT, 'features', 'support');

// ---------- helpers ----------

function* walkFiles(dir, ext) {
  if (!fs.existsSync(dir)) return;
  const entries = fs.readdirSync(dir, { withFileTypes: true });
  for (const e of entries) {
    const full = path.join(dir, e.name);
    if (e.isDirectory()) yield* walkFiles(full, ext);
    else if (e.name.endsWith(ext)) yield full;
  }
}

function readText(p) {
  try { return fs.readFileSync(p, 'utf8'); } catch { return ''; }
}

// ---------- collect step-definition patterns ----------

// Matches: defineStep(/^pattern$/, ...) or Given/When/Then(/^pattern$/, ...)
// Cucumber expression patterns are captured verbatim.
const STEP_PATTERN_RE = /(?:(?:Given|When|Then|And|But|defineStep)\s*\(\s*)(['"`])((?:[^\\]|\\.)*?)\1/g;

function collectStepPatterns() {
  const patterns = [];
  for (const f of walkFiles(SUPPORT_DIR, '.js')) {
    const text = readText(f);
    let m;
    while ((m = STEP_PATTERN_RE.exec(text)) !== null) {
      patterns.push(m[2]);
    }
  }
  // also walk step definitions alongside feature files
  for (const f of walkFiles(SPECS_DIR, '.js')) {
    const text = readText(f);
    let m;
    while ((m = STEP_PATTERN_RE.exec(text)) !== null) {
      patterns.push(m[2]);
    }
  }
  return [...new Set(patterns)];
}

// ---------- collect planks from implementation code ----------

// Match @planks("...") and @planks-provisional("...") in JS docblocks
const PLANKS_RE = /@planks\s*\(\s*(['"`])((?:[^\\]|\\.)*?)\1\s*\)/g;
const PROVISIONAL_RE = /@planks-provisional\s*\(\s*(['"`])((?:[^\\]|\\.)*?)\1\s*\)/g;

function collectPlanks() {
  const planks = [];       // { file, pattern }
  const provisionals = []; // { file, ref }
  for (const dir of IMPL_DIRS) {
    for (const f of walkFiles(dir, '.js')) {
      const text = readText(f);
      let m;
      while ((m = PLANKS_RE.exec(text)) !== null) {
        planks.push({ file: path.relative(ROOT, f), pattern: m[2] });
      }
      while ((m = PROVISIONAL_RE.exec(text)) !== null) {
        provisionals.push({ file: path.relative(ROOT, f), ref: m[2] });
      }
    }
  }
  // Also scan the same tokens outside docblocks as a fallback
  for (const dir of IMPL_DIRS) {
    for (const f of walkFiles(dir, '.js')) {
      const text = readText(f);
      // Reset lastIndex: we already consumed these regexps above.
      PLANKS_RE.lastIndex = 0;
      PROVISIONAL_RE.lastIndex = 0;
    }
  }
  return { planks, provisionals };
}

// ---------- collect @captain scenario references from feature files ----------

const SCENARIO_RE = /^\s*(?:@[^\n]+\n\s*)?(?:Scenario|Scenario Outline):\s*(.+)$/gm;
const TAG_RE = /^\s*(@\S+(?:\s+@\S+)*)\s*$/;

function collectCaptainScenarios() {
  const captainScenarios = []; // { file, name }
  for (const f of walkFiles(SPECS_DIR, '.feature')) {
    const text = readText(f);
    const rel = path.relative(ROOT, f);
    const lines = text.split('\n');
    let currentTags = [];
    for (let i = 0; i < lines.length; i++) {
      const line = lines[i];
      const tagMatch = line.match(TAG_RE);
      if (tagMatch) {
        currentTags = tagMatch[1].split(/\s+/);
        continue;
      }
      const scMatch = line.match(/^(?:Scenario|Scenario Outline):\s*(.+)$/);
      if (scMatch) {
        const name = scMatch[1].trim();
        if (currentTags.includes('@captain')) {
          captainScenarios.push({ file: rel, name });
        }
        currentTags = [];
      }
      // If line is not a tag line, reset tags
      if (!tagMatch && !line.match(/^\s*(?:Given|When|Then|And|But|Background:|Rule:|Feature:|@|$)/)) {
        currentTags = [];
      }
    }
  }
  return captainScenarios;
}

// ---------- get scenario names from feature files for provisional ref resolution ----------

function getAllScenarioNames() {
  const scenarios = []; // { file, name }
  for (const f of walkFiles(SPECS_DIR, '.feature')) {
    const text = readText(f);
    const rel = path.relative(ROOT, f);
    let m;
    while ((m = SCENARIO_RE.exec(text)) !== null) {
      scenarios.push({ file: rel, name: m[1].trim() });
    }
  }
  return scenarios;
}

// ---------- main ----------

let exitCode = 0;
const errors = [];

const patterns = collectStepPatterns();
const { planks, provisionals } = collectPlanks();
const captainScenarios = collectCaptainScenarios();
const allScenarios = getAllScenarioNames();

// Check 1: every @planks pattern matches a step-definition pattern
for (const p of planks) {
  if (!patterns.includes(p.pattern)) {
    errors.push(`@planks pattern "${p.pattern}" in ${p.file} matches no step-definition pattern`);
    exitCode = 1;
  }
}

// Check 2: every @planks-provisional ref names a @captain scenario
const captainRefs = new Set(captainScenarios.map(s => `${s.file}:${s.name}`));
for (const p of provisionals) {
  if (!captainRefs.has(p.ref)) {
    errors.push(`@planks-provisional ref "${p.ref}" in ${p.file} does not name a current @captain scenario`);
    exitCode = 1;
  }
}

// Check 3: every step-definition pattern has at least one @planks matching it
const plankedPatterns = new Set(planks.map(p => p.pattern));
for (const pat of patterns) {
  if (!plankedPatterns.has(pat)) {
    errors.push(`Step pattern "${pat}" has no @planks annotation in implementation code`);
    exitCode = 1;
  }
}

if (errors.length > 0) {
  console.error('plank-join: join failed');
  for (const e of errors) console.error(`  ${e}`);
} else {
  console.log(`plank-join: join clean — ${patterns.length} patterns, ${planks.length} planks, ${provisionals.length} provisional, ${captainScenarios.length} @captain scenarios`);
}

process.exit(exitCode);

